class TestExceptionCases:
    """异常用例测试"""

    def test_missing_required_field_raises_error(self):
        """测试缺少必需字段"""
        incomplete_user = {
            "id": 1,
            "username": "test"
            # 缺少 email 和 is_active
        }
        required_fields = ["id", "username", "email", "is_active"]
        missing_fields = [f for f in required_fields if f not in incomplete_user]
        assert len(missing_fields) > 0

    def test_invalid_email_format(self):
        """测试无效邮箱格式"""
        invalid_emails = [
            "not_an_email",
            "missing@",
            "@no_username.com",
            "spaces in@email.com"
        ]
        for email in invalid_emails:
            assert "@" not in email or " " in email

    def test_invalid_port_number(self):
        """测试无效端口号"""
        invalid_ports = [-1, 65536, 99999]
        for port in invalid_ports:
            assert port < 0 or port > 65535

    def test_invalid_url_format(self):
        """测试无效URL格式"""
        invalid_urls = [
            "not_a_url",
            "ftp://invalid",
            "://missing_scheme",
            "http://"
        ]
        for url in invalid_urls:
            assert not (url.startswith("https://") or url.startswith("http://"))

    def test_type_mismatch_integer(self):
        """测试类型不匹配-整数"""
        invalid_id = "not_an_integer"
        assert not isinstance(invalid_id, int)

    def test_type_mismatch_string(self):
        """测试类型不匹配-字符串"""
        invalid_username = 12345
        assert not isinstance(invalid_username, str)

    def test_type_mismatch_boolean(self):
        """测试类型不匹配-布尔"""
        invalid_bool = "true"  # 字符串而非布尔值
        assert not isinstance(invalid_bool, bool)

    def test_json_serialization_error(self):
        """测试JSON序列化错误"""
        # 无法序列化的对象
        class NonSerializable:
            pass

        obj = {"unserializable": NonSerializable()}
        with pytest.raises(TypeError):
            json.dumps(obj)

    def test_empty_config_section(self):
        """测试空配置部分"""
        empty_config = {
            "database": {},
            "cache": None,
            "api": {}
        }
        assert empty_config["cache"] is None or len(empty_config["database"]) == 0

    def test_path_with_invalid_characters(self):
        """测试包含无效字符的路径"""
        invalid_paths = [
            "path/with|pipe",
            "path/with*star",
            "path/with?question",
            "path/with<angle>",
        ]
        for path in invalid_paths:
            assert "|" in path or "*" in path or "?" in path or "<" in path

    def test_duplicate_user_ids(self):
        """测试重复用户ID"""
        users_with_duplicates = [
            {"id": 1, "username": "user1"},
            {"id": 2, "username": "user2"},
            {"id": 1, "username": "user3"}  # 重复ID
        ]
        ids = [u["id"] for u in users_with_duplicates]
        assert len(ids) != len(set(ids))

    def test_none_value_in_config(self):
        """测试配置中包含None值"""
        config_with_none = {
            "optional_field": None,
            "required_field": "value"
        }
        assert config_with_none["optional_field"] is None

    def test_empty_string_values(self):
        """测试空字符串值"""
        empty_strings = {"username": "", "email": ""}
        assert empty_strings["username"] == ""
        assert empty_strings["email"] == ""

    def test_whitespace_only_values(self):
        """测试仅包含空白字符的值"""
        whitespace_values = {
            "username": "   ",
            "email": "\t\n"
        }
        assert whitespace_values["username"].strip() == ""
        assert whitespace_values["email"].strip() == ""

    def test_negative_timeout(self):
        """测试负数超时值"""
        negative_timeout = {"timeout": -1}
        assert negative_timeout["timeout"] < 0

    def test_zero_cache_ttl(self):
        """测试零缓存TTL"""
        zero_ttl = {"ttl": 0}
        assert zero_ttl["ttl"] == 0

